from scipy.stats import chi2
import math

def count_breaches(returns, var_series, position):
    """Days whose loss beats that day's VaR. returns in %, var_series and position in £."""
    return sum(1 for r, v in zip(returns, var_series) if r / 100 * position < -v)

def kupiec_lr(x, n, p=0.01):
    """Kupiec's proportion-of-failures test: (LR, p-value) for x breaches in n days."""
    def xlogy(a, b):          # a * ln(b), taken as 0 when a = 0
        return 0.0 if a == 0 else a * math.log(b)
    phat = x / n
    ll_null = xlogy(n - x, 1 - p) + xlogy(x, p)
    ll_fit = xlogy(n - x, 1 - phat) + xlogy(x, phat)
    lr = max(0.0, -2 * (ll_null - ll_fit))
    return lr, float(chi2.sf(lr, 1))

