import numpy as np

def traffic_light(x):
    """Basel's zone for x breaches of a 99% VaR in 250 days."""
    if x <= 4:
        return "green"
    if x <= 9:
        return "amber"
    return "red"

def backtest_var(params, r, n_train, dist="normal", nu=5):
    """(breaches, LR, p-value) for the 99% VaR on the days after n_train (r in %)."""
    sigma = np.sqrt(garch_variance(params, r))[n_train:] / 100
    if dist == "normal":
        var = [var_normal(s, 1.0) for s in sigma]
    else:
        var = [var_t(s, 1.0, nu) for s in sigma]
    x = count_breaches(r[n_train:], var, 1.0)
    lr, p = kupiec_lr(x, len(var))
    return x, lr, p
